INSERT INTO `stays` VALUES (1,2,1,1,'White Sunrise Villa','sunrise-villa-mirissa','A beautiful sunrise villa right next to Mirissa beach with private infinity pool and ocean views.','Relax by the ocean with private pool and tropical gardens.','Full description of White Sunrise Villa... Featuring 3 spacious air-conditioned bedrooms, a sun-drenched private infinity pool, fully equipped kitchen, and incredible panoramic views of the Indian Ocean. Walk directly onto the golden sands of Mirissa Beach in seconds.',150.00,'USD',5.0,14,'https://images.unsplash.com/photo-1582268611958-ebfd161ef9cf?auto=format&fit=crop&w=800&q=80','[\"https://images.unsplash.com/photo-1582268611958-ebfd161ef9cf?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1200&q=80\"]','[\"Free Wi-Fi\",\"Air Conditioning\",\"Clean Linen\",\"Swimming Pool\",\"Kitchen\",\"Breakfast Included\"]','Beach Road, Mirissa',5.93834538,80.47742810,'https://maps.google.com/maps?q=5.93834538,80.47742810&hl=en&z=16&output=embed',NULL,'+94754361265',1,'draft',0,'2026-09-13 19:09:13'),(2,2,2,1,'Cozy Mirissa Guest House','cozy-guest-house','Affordable cozy guest house for backpackers and surfers in central Mirissa.','Comfortable AC rooms, lush garden patio, and 5 minutes to surf breaks.','Located just 5 minutes from Mirissa main surf break and beachfront restaurants. Fast Wi-Fi, air conditioning, daily housekeeping, and welcoming local hosts ready to help arrange scooter rentals and whale watching tours.',30.00,'USD',5.0,9,'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80','[\"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1584132967334-10e028bd69f7?auto=format&fit=crop&w=1200&q=80\"]','[\"Free Wi-Fi\",\"Air Conditioning\",\"Clean Linen\",\"Breakfast Included\",\"Free Parking\"]','Main Street, Mirissa',5.94721000,80.45832000,NULL,NULL,'+94754361265',1,'draft',0,'2026-09-13 19:09:13'),(3,2,3,2,'Weligama Surf Hotel & Resort','weligama-surf-hotel','Premium beachfront boutique hotel near Weligama surf break with rooftop ocean terrace.','Steps away from beginner & intermediate surf breaks with on-site board rentals.','Modern minimalist rooms, rooftop sunset cocktail terrace, and direct access to Weligama Bay surf point. Perfect for digital nomads, solo travelers, and couples seeking comfortable coastal hospitality.',80.00,'USD',5.0,16,'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=800&q=80','[\"https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=1200&q=80\"]','[\"Free Wi-Fi\",\"Air Conditioning\",\"Swimming Pool\",\"Ocean View\",\"Breakfast Included\",\"Free Parking\"]','Surf Road, Weligama',5.97254000,80.43051000,NULL,NULL,'+94754361265',1,'draft',0,'2026-09-13 19:09:13'),(4,5,2,1,'Sandy Coconut Guest','sandy-coconut-guest','Book Sandy Coconut Guest in Mirissa, Sri Lanka. Top-rated 5.0-star guesthouse on Thappawatta Road with AC rooms, breakfast, free Wi-Fi, and quick beach access.','A tranquil, top-rated 5.0-star guesthouse on Thappawatta Road in Mirissa. Comfortable AC rooms, fresh breakfast, high-speed Wi-Fi, and just minutes from the beach.','Welcome to Sandy Coconut Guest, your peaceful coastal escape in Mirissa, Sri Lanka. Proudly rated a perfect 5.0 stars with outstanding guest reviews, our guesthouse is located along serene Thappawatta Road, offering the ideal balance between quiet relaxation and easy access to the vibrant south coast.\r\n\r\nOur guest rooms feature modern air conditioning, comfortable queen and twin beds, private ensuite bathrooms with fresh hot showers, and complimentary high-speed Wi-Fi. Every morning, guests are treated to a delicious freshly prepared Sri Lankan breakfast, served in our breezy tropical garden terrace.\r\n\r\nSituated just a short 3-minute walk from the beach and within easy reach of Coconut Tree Hill, Mirissa Harbour whale watching charters, and Weligama\'s famous surf breaks. On-site scooter rentals, surf board storage, free secure parking, and round-the-clock friendly host support are available to make your stay unforgettable.',25.00,'USD',5.0,8,'https://lh3.googleusercontent.com/gps-cs-s/AHRPTWmxuvx3kI9m30yw54uqI1Zh5WFSSJ82fQf93LICcAsqfF1YKiS6qdI8r-Ze7RboaXFyH1wgvuO-5-gnDWgTsz2hIYHlt_DA0SNRqgVpJhI5Q4Ze5AS2Xycjv9Ps8gT1OTPFKkuplIvqh81x=s1360-w1360-h1020-rw','[\"https://lh3.googleusercontent.com/gps-cs-s/AHRPTWkT49W7VwSOPMUbq9T3SNIaNJAauKddfx6Wh2Hvuz4vNUq0pAbkMEkuVmzqQRlp0r1Wz4ZKhzM0HepQ7w67UlGlQq3CoKeSdmxbX0TOOAkIJUzRJVpmGLm0S-FT8aUJDSumU4BYqsXngxY8=s1360-w1360-h1020-rw\",\"https://lh3.googleusercontent.com/gps-cs-s/AHRPTWlDTuaryx927gqX1rXch4thvN6JeJiq5CQUfDl6C-nBNg37lxyX-L45Uk4HcYdpAXkozVg_xXTdE1B6Ziy43ZX7DGWJXQ7Vb3236FX0A9FIx0F4Isgd6wVZC5JLHadfQt4oTzog8jFURtA=s1360-w1360-h1020-rw\",\"https://lh3.googleusercontent.com/gps-cs-s/AHRPTWlGCBKCwkJvaAmZccGoDtSnETlCe9owhs0kzs8qY-cr_8qLOgFcWTrcFTnp7KLwuomQUqF1fmHprk7_qxMOiMM3e0jz-KNmE8EY260pKYiYiwkasLgfaKORRYeWxXgHJoID0lx_WXFNuGOx=s1360-w1360-h1020-rw\",\"https://lh3.googleusercontent.com/gps-cs-s/AHRPTWmxuvx3kI9m30yw54uqI1Zh5WFSSJ82fQf93LICcAsqfF1YKiS6qdI8r-Ze7RboaXFyH1wgvuO-5-gnDWgTsz2hIYHlt_DA0SNRqgVpJhI5Q4Ze5AS2Xycjv9Ps8gT1OTPFKkuplIvqh81x=s1360-w1360-h1020-rw\"]','[\"Free Wi-Fi\",\"Air Conditioning\",\"Clean Linen\",\"Kitchen\",\"Breakfast Included\",\"Free Parking\"]','Thappawatta Rd, Mirissa 81000, Sri Lanka',5.93781490,80.48068100,'<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3968.411979396201!2d80.47591739678951!3d5.9378149!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3ae13f904f161509%3A0xb6b4abf6db398257!2sSandy%20Coconut%20Guest!5e0!3m2!1sen!2slk!4v1789362295461!5m2!1sen!2slk\" width=\"100%\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"strict-origin-when-cross-origin\"></iframe>',NULL,'+94754361265',1,'published',1,'2026-09-13 20:26:47'),(5,1,1,5,'Thalaramba Ocean Villa','thalaramba-ocean-villa','Luxury beachfront villa in Thalaramba with ocean views, private pool, and direct beach access.','Nestled along the serene shores of Thalaramba, this private beachfront villa offers tranquility, tropical gardens, and panoramic Indian Ocean views.','Escape to peaceful Thalaramba, just minutes from bustling Mirissa. This luxury private villa features an infinity swimming pool, expansive sun terrace, fully equipped modern kitchen, and direct sandy beach access. Fall asleep to the rhythm of gentle waves and enjoy sunrise breakfast overlooking the coconut palms.',185.00,'USD',4.9,18,'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=1200&q=80','[\"https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1200&q=80\"]','[\"Free Wi-Fi\",\"Air Conditioning\",\"Swimming Pool\",\"Ocean View\",\"Clean Linen\",\"Kitchen\",\"Breakfast Included\",\"Free Parking\"]','Thalaramba Beach Road, Thalaramba',5.93800000,80.47200000,NULL,NULL,'+94754361265',1,'draft',0,'2026-09-13 20:57:34'),(6,1,1,6,'Kamburugamuwa Coastal Retreat','kamburugamuwa-coastal-retreat','Serene boutique holiday retreat in Kamburugamuwa with lush gardens and coastal serenity.','A tranquil escape in Kamburugamuwa offering spacious contemporary suites, private garden balconies, and authentic hospitality.','Discover calm living in Kamburugamuwa, situated right between Mirissa and Matara. Ideal for travelers seeking uncrowded beaches, sea breezes, and effortless access to southern Sri Lanka attractions.',95.00,'USD',4.8,12,'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80','[\"https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?auto=format&fit=crop&w=1200&q=80\"]','[\"Free Wi-Fi\",\"Air Conditioning\",\"Swimming Pool\",\"Ocean View\",\"Breakfast Included\",\"Free Parking\"]','Beach Road, Kamburugamuwa',5.94500000,80.50500000,NULL,NULL,'+94754361265',1,'draft',0,'2026-09-13 20:57:34'),(7,1,3,1,'The Nine Mirissa','the-nine-mirissa','Planning a visit to The Nine Mirissa? Explore 5+ Google Maps photos, 4.7★ reviews, exact Badugoda location, directions, pool amenities, and nearby Mirissa Beach guide.','A celebrated boutique luxury villa & pool retreat on the Badugoda hillside in Mirissa, featuring modern architecture, infinity pool, and serene ocean breezes.','The Nine Mirissa is one of the southern coast\'s most celebrated boutique architectural gems, perched peacefully on the scenic hillside along Badugoda Cross Road in Mirissa, Sri Lanka. Renowned for its minimalist tropical brutalist design, seamless indoor-outdoor living, and tranquil atmosphere, this boutique retreat has earned an exceptional 4.7-star rating with near-unanimous guest praise.\r\n\r\n### The Setting & Architecture\r\nDesigned with clean geometric lines, polished concrete, warm tropical woods, and lush native foliage, The Nine Mirissa merges contemporary aesthetics with coastal Sri Lankan tranquility. The property centers around a striking outdoor infinity swimming pool framed by sun loungers and swaying palms, providing an intimate oasis away from the main coastal road.\r\n\r\n### Location & Getting Around\r\n- **Proximity to Beach:** Located just a gentle 5 to 6-minute walk (approx. 400 meters) from the golden sands of Mirissa Beach and Weligambay Beach.\r\n- **Neighborhood:** Tucked into the peaceful Badugoda hillside neighborhood, offering quiet nights free from beach road traffic while keeping beachfront restaurants, surf schools, and sunset cocktail lounges within immediate walking distance.\r\n- **Whale Watching & Harbour:** Approximately 3 minutes by tuk-tuk to Mirissa Fisheries Harbour for early morning blue whale and dolphin excursions.\r\n\r\n### Highlights & Signature Experiences\r\n- **Outdoor Swimming Pool:** A centerpiece infinity-style pool with panoramic garden views and comfortable shaded loungers.\r\n- **Rooftop Yoga & Wellness Shala:** An elevated open-air pavilion designed for morning yoga, meditation, and sunset golden-hour stretches overlooking the coconut canopies.\r\n- **Ocean & Garden Vistas:** Well-appointed private terraces offering refreshing sea breezes and sunrise views over southern palm tops.\r\n- **Curated Dining:** Known for its fresh, locally sourced breakfast offerings, seasonal tropical juices, and ocean-to-table culinary attention.\r\n\r\n*Note: MirissaStays provides this listing as a verified local destination guide for travelers visiting Mirissa. Direct reservations are managed through the property\'s official channels. If you are looking for verified guesthouses and villas with direct WhatsApp host booking, explore our recommended nearby stays below.*',0.00,'USD',4.7,99,'https://lh3.googleusercontent.com/gps-cs-s/AHRPTWk9SmHRKiAyHigoHLpjDTNE1wW8wCHvcLoml_NS67tpdU59ZVc0q1d3FxhZULSYLIR6WDJg23PFUwSqgtRCGMVqjm7uwTmhBbeFLWsJ7uXMpeqnooMlPAuMfIBfyZ8kNRWxJ3Rs=s1360-w1360-h1020-rw','[\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWmPmge3G9z1r6UdYaBFw0MGpsskZMu_ZTABi9LXkvnGNgwSO74R55j0YveBrNG59fnvj0o5aVz39yaiAfueJ-dYTVNtBNhvAcNmpsv5N2NAxndfzXaMGqohArhuvXu9H2ycnnVY0LQuvvbK=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWnAz8zdLzGWovnXCAIbZAwQQyxZuRvQfqskEvhhRYxn1RJOV-SxjxQqvS4d3UXRNcJfawXEoOIiTQxlwp5lDngW0awvGTx5NdlFHTXVQIh29jaAtXTa9LIi0-HIpY5Qqk-rpSq_OA=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWkh9ggc8yDftVe3FcOGTPv2nhvT_0G8nIPnSvmP6XNqbmDTC8GdnG492scYysAxMC80hDnQ2SNPFd5ldlXyooYbpjYmJtNr-_P9vPKI5GwYrJTUS7rq2KFZxMTIfA9vthKB-GAYp9nuOU91=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWl0zdYHiez1X25zxE1jzj2K7rWKnIT9Au0gpHwuu8z34s-_EhJKDdakCn4RJ2piZuLz8BOAWdQ6AxexvsKN63Wd1CBsFWhnTGWzqd8kV6uqKftDtUNumGlmWNJSSqHB-QknJ4P4Eg=s1360-w1360-h1020-rw\"]','[\"Free Wi-Fi\",\"Air Conditioning\",\"Clean Linen\",\"Swimming Pool\",\"Ocean View\",\"Free Parking\"]','Badugoda Cross Road, Mirissa 81740, Sri Lanka',5.94511870,80.45222020,'https://maps.google.com/maps?q=5.9451187,80.4522202&hl=en&z=16&output=embed','https://share.google/rmgvbD0RNfFsuvSRh','',0,'published',1,'2026-09-17 19:42:45'),(8,1,1,1,'Mirissa Hills','mirissa-hills','Discover Mirissa Hills in Henwalle, Mirissa. Explore 4.5★ reviews, working cinnamon plantation, the Cinnamon Museum, 5+ photos, map directions, and travel tips.','A legendary working cinnamon plantation, Cinnamon Museum, and luxury boutique estate offering 360° panoramic views over the southern Sri Lankan hills and ocean.','Mirissa Hills is an extraordinary boutique estate, working cinnamon plantation, and cultural landmark perched atop the verdant coastal hills above Weligama Bay and Mirissa in southern Sri Lanka. Rated an impressive 4.5 stars with 284+ Google reviews, this historic multi-acre property combines authentic agricultural heritage with breathtaking 360-degree views across lush tropical valleys, distant mountains, and the Indian Ocean.\n\n### The Working Cinnamon Plantation & Museum\nMirissa Hills is globally celebrated for its dedicated commitment to preserving Sri Lanka\'s indigenous spice legacy:\n- **The Cinnamon Museum:** Widely recognized as the world\'s first museum dedicated exclusively to the history, agricultural processing, and botanical varieties of pure Ceylon cinnamon (Cinnamomum verum). Visitors can discover traditional cinnamon peeling demonstrations and learn about ancient spice trading routes.\n- **The Estate Grounds:** Spanning rolling emerald hillsides planted with cinnamon shrubs, rubber trees, pepper vines, and tropical fruit orchards that attract vibrant birds, peacocks, and playful monkeys.\n\n### Distinct Properties of the Estate\nThe estate features three unique heritage settings:\n1. **Mount Cinnamon:** A striking contemporary villa designed by architect Channa Daswatte, set high upon the hilltop with a sweeping infinity pool that appears to spill into the jungle canopy below.\n2. **The Cinnamon Museum Rooms:** Intimate heritage suites integrated seamlessly with the museum grounds.\n3. **The Bungalow:** A meticulously restored antique walauwa (traditional colonial manor house) nestled at the base of the plantation amid manicured courtyard gardens.\n\n### Getting to Mirissa Hills\n- **Directions:** Located along Henwalle Road, approximately 1 kilometer inland from the main coastal road (A2) past the Polwathumodara Bridge.\n- **Distance:** An 8-minute tuk-tuk ride from Weligama Bay surf point and approximately 10 to 12 minutes from Mirissa Beach and Coconut Tree Hill.\n- **Navigation:** Accessible by car, tuk-tuk, or scooter with dedicated on-site parking at the estate entrance.\n\n*Note: MirissaStays publishes this guide to help travelers discover unique heritage attractions and sights across Mirissa. Direct bookings for Mirissa Hills are operated through the estate. To explore verified local guesthouses and beachfront villas with instant host contact, browse our recommended stays below.*',0.00,'USD',4.5,284,'https://lh3.googleusercontent.com/gps-cs-s/AHRPTWkXxyTY3ZOrNN9YQnMjR8ivNxW_xorLY275SgxzePgaiO4ssTs2ecJSNtONnhMMDt8dUhEvGxFfY9lw6Q3UdbiPfE_SgtvxGUHYXXeQiDS-wmrGyrHm7jnagJUKMjEpQKsKFlY=s1360-w1360-h1020-rw','[\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWkQnEshQypve8waNJbjd1iXwJwGCS_5W63uRlwqH5jMMFHTWzRk0Gng5SySfNMnFH7bCgljslnlqmop1S9Z7Vjwj8WVID523Z5SyhQ8Xk-HZiXJM_8pZrl11JrFcW_lWFL89N6UGA=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWlaB9bOZiTvRd7f4ohzixveZ2z5_evhNSRIhiQxQiHo3hdA19tlBk4-iPfe4Rs-DijR958EHdsnn_N4JHRW-6afaOHlOOmhR2hVB93M4EnM04upi3RdqjDsgvduA3Q16-1g5UC-=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWllzXBZOrJtAIkLZMY0wEe8smDlAo8t7PxLnvWZfCcZOHtPPpES7qH8rsXzzAf8y4oL6ZaK8_CQ5lph0xkqPFZoAFb20YOFvTwD9zNwd-hic3lT6sOXC_F8Av0a58O4jDy3OXU=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWlj0rs3fbK5Codum_WIJ4a_vBwwK11boFb-sjWoTwIsW_BgvUkAjNkYcGIzfCnjTDo3_y1DkWChMtTATyZrLPvL9ijebIRxUbXh5s2dvkYZaaV4QRFwzblFHqbUN2X4GAOAgPtE_Q=s1360-w1360-h1020-rw\"]','[\"Swimming Pool\",\"Ocean View\",\"Free Wi-Fi\",\"Free Parking\",\"Clean Linen\",\"Breakfast Included\"]','Henwalle Road, Henwalle, Mirissa, Sri Lanka',5.96335380,80.46641830,'https://maps.google.com/maps?q=5.9633538,80.4664183&hl=en&z=16&output=embed','https://share.google/cCK65MX5rMN2sPr2C','',0,'published',1,'2026-09-17 19:42:45'),(9,1,3,1,'Asaya Sands Mirissa','asaya-sands-mirissa','Discover Asaya Sands Mirissa, a luxury 4.9★ beachfront hotel on Mirissa Beach. View 5+ photos, location map, reviews, swimming pool amenities, and guest guide.','An exquisite beachfront luxury boutique hotel & coastal sanctuary in Mirissa featuring panoramic ocean views, private infinity pool, and fine seaside dining.','Asaya Sands Mirissa is an extraordinary 5-star beachfront luxury hotel and private coastal sanctuary set directly along the tranquil sands of Mirissa on Sri Lanka\'s sun-kissed southern coast. Garnering an exceptional 4.9-star rating with over 207 glowing Google reviews, Asaya Sands is revered by international travelers for its barefoot luxury philosophy, impeccable architectural elegance, and warm Sri Lankan hospitality.\r\n\r\n### Beachfront Architecture & Coastal Design\r\nPositioned right where lush tropical palms meet the golden sands of the Indian Ocean, Asaya Sands features a masterfully curated blend of tropical modernism and relaxed bohemian coastal aesthetics. Every suite and common pavilion is oriented to catch cooling ocean breezes and showcase sweeping, unobstructed panoramas of the rolling waves and fiery south coast sunsets. The property is anchored by a glistening beachfront swimming pool lined with plush daybeds and private cabanas.\r\n\r\n### Luxurious Suites & Oceanfront Living\r\n- **Oceanfront Master Suites:** Expansive air-conditioned living sanctuaries boasting floor-to-ceiling glass doors, private timber decks, handcrafted king beds, and open-air rain showers enveloped by tropical greenery.\r\n- **Direct Beach Access:** Step straight from your private terrace onto the pristine sands of Mirissa\'s peaceful eastern bay, ideal for morning walks, private sunbathing, and watching sea turtles cruise the shallows.\r\n- **Curated Ocean Dining:** Indulge in artisanal breakfasts, freshly caught seafood grill dinners, tropical smoothie bowls, and signature sunset cocktails served against the soundtrack of breaking waves.\r\n\r\n### Prime Mirissa Location & Highlights\r\n- **Beach Proximity:** Direct beachfront frontage with immediate ocean access.\r\n- **Coconut Tree Hill:** A scenic 10-minute stroll along the shoreline leads directly to Mirissa\'s most famous palm-covered promontory.\r\n- **Whale Watching & Water Sports:** Mirissa Harbour is just a 5-minute tuk-tuk ride away for world-renowned blue whale watching excursions, guided snorkeling, and surf lessons.\r\n- **Nightlife & Dining:** A peaceful, private haven positioned just minutes away from Mirissa\'s beachfront seafood bistros, vibrant cafes, and sunset bars.\r\n\r\n*Note: MirissaStays provides this comprehensive guide to assist travelers in discovering premier luxury boutique hotels across Mirissa. Direct reservations and inquiries are handled directly by the hotel. To discover verified nearby guesthouses and villas with instant WhatsApp host booking, explore our recommended accommodations below.*',0.00,'USD',4.9,207,'https://lh3.googleusercontent.com/gps-cs-s/AHRPTWn3MgXBLoi2gnBm085wY4G-NSrEmzeEMlfkhUqRR83NrIhP57P9tWf_Fh2pl684sWZquiesztCy02Vifi-ObpXfFtDTbZ6DYw27MnJUXYrChH7SGGE5ERtkSEZs52oujkq-FmWozhZFwD9b=s1360-w1360-h1020-rw','[\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWkN8l0FOnJJHIZtaLAmed3Orq5_G4CcV0UhpwwoEwsK3S33C20fyKbfZqju3OBa4-smjmTCGug4RZCOkHdoPHyR2Z8jwvD6nW7Og8JR0Vc7T10rr9_0xDSosD5PV5atNMyP8yPWC22iXKE=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWn611pMtgfZ4lSnJPFlZu6EuJfZSGeH370atqks2HZFKWU-WVCwS6oWdwRpC2Ve-jLv17_Hl2-mR5HLG3NIaepcy_4rtf9ImKSNE9bXLYc2rvCufjvZA2dhLWxbNMyEY3QjiRF2c9Qyk7pO=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWlBRIR9jpfV6lVT4l4nEhDiqJ5JDbAiAo-Zbzz_HwsfZOS8kk3CUhhYRT9VL8nNKCgO3GE4Zzq_BYtRFawOGcPz8Ojm1Qs3jGZTkli70OJa3x0VqnGyE7PyFf4lqYn61tbnEClctkaQBwZQ=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWk39xg92IiicBod-izAPcEoVHU-htkoJHZ5iSA_WEmi__u5SN5b66v8okfH8VvVyH3CwvzbDz3ym3WZI0GozfVJ01ocrG6Sv_XJkPnUsm5RGy5CiwCMUG6jX4rSPgE7271LnDPXCwdLvren=s1360-w1360-h1020-rw\"]','[\"Swimming Pool\",\"Ocean View\",\"Free Wi-Fi\",\"Air Conditioning\",\"Breakfast Included\",\"Free Parking\"]','WFQF+F3C, Mirissa 81740, Sri Lanka',5.93852780,80.47213890,'https://maps.google.com/maps?q=5.9385278,80.4721389&hl=en&z=16&output=embed','https://share.google/s3mftkgwCLWra5tJ0','',0,'published',1,'2026-09-17 20:28:56'),(10,1,3,1,'Paradise Beach Club','paradise-beach-club','Explore Paradise Beach Club in Mirissa, Sri Lanka. Iconic 4.0★ beachfront resort on Mirissa Beach with swimming pool, 5+ photos, reviews, location map & guide.','One of Mirissa\'s most famous beachfront resorts directly on Mirissa Beach, featuring direct ocean access, large swimming pool, and tropical beach club.','Paradise Beach Club is one of Mirissa\'s longest-standing and most iconic beachfront resorts, positioned right on the golden crescent of Mirissa Beach in southern Sri Lanka. With over 1,300 verified Google reviews, this premier beach resort offers direct sea access, a vast lagoon swimming pool overlooking the ocean, and front-row seats to Mirissa\'s famous coastal sunsets.\r\n\r\n### Iconic Beachfront Resort Experience\r\nNestled directly along the sand, Paradise Beach Club combines relaxed tropical island life with full resort amenities. Guests step immediately from the poolside terrace onto the golden shores of Mirissa Beach, where tranquil swimming zones, surf breaks, and coral reefs are just footsteps away. The centerpiece is the large oceanfront swimming pool framed by swaying palm trees, dedicated sun loungers, and a lively beach bar serving fresh coconut drinks and signature cocktails.\r\n\r\n### Accommodation & Amenities\r\n- **Beachfront & Pool View Rooms:** Air-conditioned guest rooms and family suites with private balconies overlooking either the turquoise swimming pool or the Indian Ocean waves.\r\n- **Oceanfront Restaurant & Bar:** Dine with your feet in the sand on fresh southern Sri Lankan curries, grilled jumbo prawns, catch-of-the-day seafood, and continental breakfast favorites.\r\n- **Ayurveda & Wellness:** On-site traditional Ayurvedic massage and wellness treatments designed to rejuvenate body and mind after a day of beach activities.\r\n\r\n### Location & Nearby Attractions\r\n- **Mirissa Main Beach:** Direct walk-out access to the main beachfront promenade, surf schools, and sunset dining spots.\r\n- **Parrot Rock:** Located just 200 meters down the beach, offering panoramic 360-degree views over Mirissa Bay.\r\n- **Mirissa Harbour Whale Watching:** Just 4 minutes by tuk-tuk to the harbour for early morning blue whale and spinner dolphin excursions.\r\n- **Coconut Tree Hill:** A picturesque 15-minute coastal walk to the southeast.\r\n\r\n*Note: MirissaStays publishes this guide as a verified directory of Mirissa\'s prominent beachfront resorts. Direct reservations are operated through the resort\'s official channels. If you are looking for local boutique guesthouses and villas with direct WhatsApp host booking, explore our recommended nearby stays below.*',0.00,'USD',4.0,1300,'https://lh3.googleusercontent.com/gps-cs-s/AHRPTWk15_ey0OuFx4AcrSiCrs9AjD6xlSt15Llurr8-FZQ5D6cBBgZxliTXEi3H_mNWkLjA21fxp6Gy_r_YR3MrCVgkcnHQEFLgg9Sz1TDxF8nlt7EhhOs--zUOuWA2By0AwLf9DWev5Ae2dy1l=s1360-w1360-h1020-rw','[\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWlvBMwE-SQzHQ3h1c--1rrXk7n2M7JMtSLVtR8ODWHHiB35XOsY5ux0JQMPOEO6stW6-EaZFvI_w7rjfPxckCLWnLNR9hlB4B7eRPPsfmWxH_YIzmrtoiZgs_jAUg_-wPneBxHDVCINGZ_d=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWlGfX3HdF4eMn-7c16dziQH4kUNpvl_hbU6HSsOTH1cHzEpBD9A7rqz4E0qBu_lFbybXBSDYmWyCPj2Mvh_JF6xsMuzI36fKS7GZ78Xid9q4Fth_uOqx1wPY2LqEre_hdm7qs0V=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWlH6XVr7gkyHGjAC0w3A8Lep-oqSAEHAU6V0Wn1RDW5UrpcHkrejxKVypoYIp3UxYmSAZfWDnWBbvpuuqA_8iB2zpsFyBLTb2JtqMCpWoi5SVBnMekTm84fagmVUG9IYyw4HAo7=s1360-w1360-h1020-rw\",\"https:\\/\\/lh3.googleusercontent.com\\/gps-cs-s\\/AHRPTWk96yskvT1evI1495DAc-EYyLkHZ3tCjx3e9WxrRMGET3076NKbSiNILCPwcw7OcLPtlv2z3ubWqHmFERUpEYjmSWW9ZUZKcFt-Bnd8KOKUtq4ubmI-vELLxF7ESx3rJ15gO4gu_5sGxCSM=s1360-w1360-h1020-rw\"]','[\"Swimming Pool\",\"Ocean View\",\"Free Wi-Fi\",\"Air Conditioning\",\"Clean Linen\",\"Breakfast Included\",\"Free Parking\"]','140, Ven. Gunasiri Mahimi Mawatha, Mirissa 81740, Sri Lanka',5.94520000,80.45780000,'https://maps.google.com/maps?q=5.9452,80.4578&hl=en&z=16&output=embed','https://www.google.com/travel/search?ts=CAESCgoCCAMKAggDEAAaHBIaEhQKBwjqDxAJGBMSBwjqDxAJGBQYATICEAAqBwoFOgNMS1I&qs=CAEyEkNna0l2LU96eW96RzRTb1FBUTgIQgkRDCJOV9Rq1XlCCRGqtgXPmmsufkIJESN4nMNCFAYc&utm_campaign=sharing&utm_medium=link_btn&utm_source=htls','',0,'published',1,'2026-09-17 20:28:56'),(11,1,3,2,'Mandara Resort Mirissa','mandara-resort-mirissa','Discover Mandara Resort Mirissa, a 5-star beachfront resort on the Indian Ocean. Explore 4.1 star reviews, 2070+ guest ratings, outdoor pool, spa, and location guide.','A luxurious 5-star beachfront resort set directly on the Indian Ocean in Mirissa, Weligama, featuring an outdoor pool, spa, fitness center, and poolside international dining.','Mandara Resort Mirissa is an upscale 5-star beachfront resort perched along the shimmering shores of the Indian Ocean in Mirissa, Weligama, southern Sri Lanka. Boasting an impressive 4.1-star rating with over 2,070 verified Google reviews, this premier resort delivers a seamless blend of tropical luxury, warm Sri Lankan hospitality, and world-class resort amenities just steps from the sand.\r\n\r\n### Location & Surroundings\r\nSituated at 416 A, Mirissa, Weligama 81740, Mandara Resort enjoys an unrivaled beachfront position on the Indian Ocean. The resort is conveniently located just a 2-minute walk from Polwathumodara train station, making it easily accessible by rail or road from Colombo and Galle. Mirissa Fisheries Harbour - the gateway to world-renowned Blue Whale watching excursions - is within easy reach.\r\n\r\n### Rooms & Suites\r\nMandara Resort bright, airy guest rooms and suites are elegantly appointed with flat-screen televisions, complimentary high-speed Wi-Fi, and thoughtful tea and coffee-making facilities. Upgraded room categories feature separate living areas, whirlpool tubs, or exclusive private plunge pools surrounded by lush tropical gardens.\r\n\r\n### Dining & Poolside Restaurant\r\nThe resort signature poolside restaurant serves an enticing international cuisine menu crafted from fresh local produce and catch-of-the-day seafood. Guests can enjoy breakfast, lunch, and dinner al fresco beside the sparkling outdoor swimming pool, or unwind at the casual bar with signature tropical cocktails.\r\n\r\n### Wellness, Pool & Spa\r\n- **Outdoor Swimming Pool:** A gleaming lagoon pool ringed by sun loungers, parasols, and lush tropical greenery.\r\n- **Spa & Wellness Centre:** Offering traditional Ayurvedic treatments, deep-tissue massages, and holistic wellness rituals.\r\n- **Fitness Centre:** A fully equipped gymnasium with modern cardio and strength training equipment, available 24 hours.\r\n\r\n### Key Amenities\r\n- Direct beachfront access to the Indian Ocean\r\n- Outdoor swimming pool\r\n- Spa & beauty treatments\r\n- Fitness centre / gymnasium\r\n- Poolside international restaurant\r\n- Casual bar & lounge\r\n- 24-hour room service\r\n- Free high-speed Wi-Fi throughout\r\n- Free on-site parking\r\n- Airport shuttle service (on request)\r\n- Air-conditioned rooms & suites\r\n- Wheelchair accessible property\r\n\r\n### Getting There\r\n- **By Train:** 2-minute walk from Polwathumodara Railway Station on the Colombo-Matara Coastal Line.\r\n- **By Road:** Located on the A2 Southern Coastal Highway at 416 A, Mirissa, Weligama 81740.\r\n- **By Tuk-Tuk:** Approximately 5 minutes from Weligama town center and 8 minutes from Mirissa Beach.\r\n\r\n*Note: MirissaStays publishes this guide as a verified directory of premier beachfront resorts. Direct reservations are managed through the resort official channels at mandarahotels.com.*',0.00,'USD',4.1,2070,'https://d28lgmef6a1iew.cloudfront.net/sites/3/2025/09/mandara-resort-mirissa-810_8030.jpg?w=860&h=840&&fit=crop&crop=center&auto=format&q=50','[\"https:\\/\\/d28lgmef6a1iew.cloudfront.net\\/sites\\/3\\/2025\\/09\\/mandara-resort-mirissa-810_8030.jpg?w=860&h=840&&fit=crop&crop=center&auto=format&q=50\",\"https:\\/\\/d28lgmef6a1iew.cloudfront.net\\/sites\\/3\\/2026\\/05\\/Sri-Lankan-Residents-Offer-at-Mandara-Resort-520x615-1.jpg?w=520&h=615\",\"https:\\/\\/cf.bstatic.com\\/xdata\\/images\\/hotel\\/max1024x768\\/73241181.jpg?k=8e3ce973665c205beef7d64da5d1ea7b02b563644e2f82b1dd8fdb8f0042cb87&o=\",\"https:\\/\\/cf.bstatic.com\\/xdata\\/images\\/hotel\\/max1024x768\\/546440268.jpg?k=6066da587a4b7bbf064d0b78ac2b0c130068bc38a5ff082686c0bee2ef1b2f22&o=\",\"https:\\/\\/cf.bstatic.com\\/xdata\\/images\\/hotel\\/max1024x768\\/73240878.jpg?k=ff6537a25e15f9ac77a60f08a12f5d1d75c4fb77f4d107ffb91aebc112f4e2b0&o=\"]','[\"Free Wi-Fi\",\"Air Conditioning\",\"Swimming Pool\",\"Ocean View\",\"Breakfast Included\",\"Free Parking\"]','416 A, Mirissa, Weligama 81740, Sri Lanka',5.96426140,80.45385180,'<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3968.2210435145907!2d80.45127687452482!3d5.96426139402046!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3ae1155fe6a3d2f3%3A0x22625276054f51ce!2sMandara%20Resort%20Mirissa!5e0!3m2!1sen!2slk!4v1789923479934!5m2!1sen!2slk\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"strict-origin-when-cross-origin\"></iframe>','https://maps.app.goo.gl/t7p5jbjbd8ZRVikq5','+94412253993',0,'published',1,'2026-09-20 10:36:44'),(12,1,2,1,'PearlDrop Waves Mirissa','pearldrop-waves-mirissa','Discover PearlDrop Waves Mirissa, a top-rated boutique guesthouse with indoor pool, ocean-view balconies, on-site restaurant & 915+ 9.2★ guest reviews.','A premier boutique luxury guesthouse featuring 8 air-conditioned ocean-view rooms, an indoor swimming pool, open rooftop deck, and on-site restaurant in Mirissa.','PearlDrop Waves Mirissa is an extraordinary boutique luxury guesthouse nestled peacefully along Kalugalluwa Road in Mirissa, Sri Lanka. Boasting a stellar 9.2/10 \"Wonderful\" rating with more than 915 verified traveler reviews, this coastal haven delivers an exceptional stay combining seaside intimacy, contemporary amenities, and genuine Sri Lankan hospitality led by host Eranga.\r\n\r\n### Coastal Setting & Rooftop Views\r\nSituated just a 1-minute walk from the tranquil sands of Thalaramba Beach and within comfortable walking distance of Mirissa Beach and iconic Coconut Tree Hill, PearlDrop Waves offers a peaceful, scenic haven away from noisy road traffic. The property features a panoramic open-air roof deck overlooking coconut palms and the azure Indian Ocean, perfect for sunset lounging, stargazing, and morning yoga.\r\n\r\n### Rooms & Sea-View Suites\r\nPearlDrop Waves features 8 elegantly furnished, air-conditioned guest accommodations:\r\n- **Private Sea-View Balconies:** Wake up to refreshing ocean breezes and scenic coastal panoramas from your private terrace.\r\n- **Modern Ensuite Bathrooms:** Equipped with walk-in hot water rain showers, complimentary toiletries, and fresh towels.\r\n- **In-Room Comforts:** Flat-screen televisions, complimentary high-speed Wi-Fi, writing work desk, mini refrigerator, and electric kettle with tea and coffee maker.\r\n- **Family & Double Accommodations:** Thoughtfully appointed king-bed rooms designed for couples, digital nomads, and small families.\r\n\r\n### Swimming Pool & Wellness\r\n- **Indoor Swimming Pool:** A pristine, private swimming pool ideal for refreshing dips after sunbathing or exploring the southern coast.\r\n- **Sun Deck & Open Terrace:** Lounge chairs and shaded relaxation spaces surrounded by lush coastal greenery.\r\n\r\n### Dining & On-Site Restaurant\r\nThe on-site poolside restaurant serves a delicious range of culinary favorites:\r\n- **Fresh Daily Breakfast:** Enjoy generous Sri Lankan and continental breakfasts with tropical fruits, freshly brewed Ceylon tea, and smoothies.\r\n- **Diverse Cuisine:** Expertly prepared seafood, Asian, American, Chinese, and authentic Sri Lankan curries, with extensive vegetarian and vegan options.\r\n- **Romantic Candlelit Dinners:** Intimate evening meals arranged under the stars upon request.\r\n\r\n### Key Amenities & Highlights\r\n- 1-minute walk to Thalaramba Beach (frequent sea turtle sightings)\r\n- Indoor swimming pool and sun loungers\r\n- Open rooftop ocean observation deck\r\n- Free high-speed Wi-Fi in all rooms and public areas\r\n- Free private on-site parking\r\n- Air conditioning in all bedrooms\r\n- On-site restaurant and room service\r\n- Tour assistance for Blue Whale watching charters, snorkeling, and scooter rentals\r\n\r\n### Getting Around\r\n- **Thalaramba Beach:** 1 minute walk.\r\n- **Coconut Tree Hill:** 12 to 15 minutes walk along the scenic coastline.\r\n- **Mirissa Beach & Parrot Rock:** 4 to 5 minutes by tuk-tuk or scooter.\r\n- **Mirissa Fisheries Harbour (Whale Watching):** 7 minutes by tuk-tuk.\r\n- **Weligama Bay Surf Point:** 10 minutes by tuk-tuk.\r\n\r\n*Note: MirissaStays provides verified listings and curated guides for travelers exploring southern Sri Lanka. You can check live rates, room availability, and reserve directly via Booking.com using the link provided.*',42.00,'USD',4.9,915,'https://cf.bstatic.com/xdata/images/hotel/max1024x768/592338106.jpg?k=4d95cab8592c739dfa00ab82631a0a5a60554920c4339e340b6fb4ad2216483f&o=','[\"https:\\/\\/cf.bstatic.com\\/xdata\\/images\\/hotel\\/max1024x768\\/592338106.jpg?k=4d95cab8592c739dfa00ab82631a0a5a60554920c4339e340b6fb4ad2216483f&o=\",\"https:\\/\\/cf.bstatic.com\\/xdata\\/images\\/hotel\\/max1024x768\\/507277815.jpg?k=896b7a25d12e03d9f690293f8e2e4841445f1762f3c4c176bea75000267f772a&o=\",\"https:\\/\\/cf.bstatic.com\\/xdata\\/images\\/hotel\\/max1024x768\\/507277879.jpg?k=cde17394a61d5888427d099dda4bba20531651ea3b84defb6b54e964c4ecda99&o=\",\"https:\\/\\/cf.bstatic.com\\/xdata\\/images\\/hotel\\/max1024x768\\/507278950.jpg?k=8b1b7800b4210b62911d9db7af7fe4d724d97b72e1d00870572c2098ccc202c9&o=\",\"https:\\/\\/cf.bstatic.com\\/xdata\\/images\\/hotel\\/max1024x768\\/507279044.jpg?k=db629796598547a92f2b8465529350260c1815075903dd523d8e1158ce2e9260&o=\